local SeasonHelper = {}local FutServerTypesDefinition, TableUtil = ...local FutResult = FutServerTypesDefinition.FUT.FutMatchResultfunction SeasonHelper._findAwards(obj, rewardType)  local c = 0  local s = 0  do    do      for i = 1, #obj do        if obj[i][rewardType] ~= nil then          c = c + 1          s = s + obj[i][rewardType]        end      end    end  end  return {count = c, sum = s}endfunction SeasonHelper.createPrize(awards, loc, futStore, title, step, point, styleIdx, awardList, highlighted, color)  local current_step = {}  local coins = SeasonHelper._findAwards(awardList, "coins")  if coins.sum ~= 0 then    local data = {}    data.title = loc.LocalizeString(title)    data.step = loc.LocalizeString(step)    data.points = loc.LocalizeInteger(point) .. " " .. loc.LocalizeString("LTXT_SEASONS_HUB_POINTS")    data.prizesIcon = "0"    data.styleIndex = styleIdx    data.value = loc.LocalizeInteger(coins.sum)    data.currency = loc.LocalizeString("LTXT_CMN_COINS")    data.highlighted = highlighted    data.color = color    table.insert(current_step, data)  end  do    do      for i, i in ipairs(awardList) do        if i.itemId ~= nil then          local data = {}          data.title = loc.LocalizeString(title)          data.step = loc.LocalizeString(step)          data.points = loc.LocalizeInteger(point) .. " " .. loc.LocalizeString("LTXT_SEASONS_HUB_POINTS")          data.prizesIcon = "3"          data.styleIndex = styleIdx          data.value = ""          data.currency = loc.LocalizeString("LTXT_MOB_POSTMATCH_REWARD_PACK_LINE2")          data.highlighted = highlighted          data.color = color          table.insert(current_step, data)        end      end    end  end  do    do      for i, i in ipairs(awardList) do        if i.packId ~= nil then          local data = {}          data.title = loc.LocalizeString(title)          data.step = loc.LocalizeString(step)          data.points = loc.LocalizeInteger(point) .. " " .. loc.LocalizeString("LTXT_SEASONS_HUB_POINTS")          local pack = futStore.GetRewardPackInfo(i.packId)          data.prizesIcon = tostring(pack.assetID + 2) .. "s"          if pack.assetPath then            data.assetPath = pack.assetPath          end          data.styleIndex = styleIdx          data.value = loc.LocalizeString("LTXT_MOB_POSTMATCH_REWARD_PACK_LINE1")          data.currency = loc.LocalizeString("LTXT_MOB_POSTMATCH_REWARD_PACK_LINE2")          data.highlighted = highlighted          data.color = color          table.insert(current_step, data)        end      end    end  end  table.insert(awards, {data = current_step})endfunction SeasonHelper.getMatchHistItem(obj, loc)  local data = {}  TableUtil.print(obj)  data.str = tostring(obj.hisScore) .. " " .. loc.LocalizeString("LTXT_COMMON_SCORE_SEPARATOR") .. " " .. tostring(obj.myScore)  if obj.isHomeGame then    data.str = tostring(obj.myScore) .. " " .. loc.LocalizeString("LTXT_COMMON_SCORE_SEPARATOR") .. " " .. tostring(obj.hisScore)  end  if obj.result == FutResult.FUT_MATCHRESULT_WIN then    data.result = 0  elseif obj.result == FutResult.FUT_MATCHRESULT_DRAW then    data.result = 2  elseif obj.result == FutResult.FUT_MATCHRESULT_LOSS then    data.result = 1  end  return dataendreturn SeasonHelper